# port scan plugin
yakit.AutoInitYakit()

CVEs = []
addCVE = func(cve, rules, score, severity, titleZh, titleEn) {
    if (str.Contains(rules, ",")) {
        rules = str.Join(x.Map(str.Split(rules, ","), func(i) {
            return sprintf(`(%v)`, str.ReplaceAll(str.TrimSpace(i), ".", `\.`))
        }), "|")
    }
    CVEs = append(CVEs, {
        "cve": cve,
        "rule": rules,
        "score": score,
        "severity": severity,
        "titleZh": titleZh,
        "titleEn": titleEn, 
    })
}

addCVE("CVE-2004-0042", "1.1.3","5.0", "MEDIUM", "vsftpd合规检查-CVE-2004-0042", "Vsftpd identifies valid user name vulnerabilities")
addCVE("CVE-2004-2259", "1.2.0, 1.2.1","5.0", "MEDIUM", "vsftpd合规检查-CVE-2004-2259", "Beasts vsftpd 1.2.0/1.2.1 Crash DOS")
addCVE("CVE-2009-4457", "1.2a, 1.2b","7.5", "HIGH", "vsftpd合规检查-CVE-2009-4457", "Vsftpd_webmin_module Unspecified vulnerability")
addCVE("CVE-2011-0762", "0.[0-9].[0-1]?[0-9], 1.[0-2].[0-3], 2.0.[0-7], 2.1.[0-2], 2.2.[0-2], 2.3.[0-1]","4.0", "MEDIUM", "vsftpd合规检查-CVE-2011-0762", "Beasts vsftpd up to 0.0.13 ls.c vsf_filename_passes_filter DOS")
addCVE("CVE-2011-2523", "[0-2].[0-9].[0-9][0-9]?, 3.0.[0-1][0-9]?","5.0", "MEDIUM", "vsftpd合规检查-CVE-2011-2523", "Vsftpd Code Execution")


handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen() {
        return
    }

    if result.Fingerprint == nil {
        return
    }
    if str.MatchAllOfRegexp(result.GetServiceName(),"(?i)vsftpd") {
    yakit.Info("cves: %d", len(CVEs))

        x.Foreach(CVEs, func(i) {
            defer func{
                err = recover()
                if err != nil {
                    yakit.Error("Vsftpd CVE 合规检查失败：%v", err)
                }
            }
            if !str.MatchAllOfRegexp(result.Fingerprint.Version, i.rule) {
                return
            }

            target := str.HostPort(result.Target, result.Port)
            targetOutput := sprintf("(%v)", target)
            risk.NewRisk(
                target, 
                risk.title(sprintf(`%v`,  i["titleZh"])),
                risk.titleVerbose(sprintf(`%v`, i["titleZh"])),
                risk.type("cve-baseline"),
                risk.typeVerbose("CVE基线检查"),
                risk.parameter(result.Fingerprint.Banner),
                risk.potential(true),
                risk.level("low"),
                risk.details(i),
                risk.cve(i.cve),
            )
            println(i.cve)
        })
    }
}
